// Markets tab: publicly traded AI-related companies + private AI unicorns.
// Data: data/markets.js (window.MARKETS), generated by tools/refresh-markets.py. Missing values render as a dash.
(function(){
const M = window.MARKETS, U = window.U, esc = U.esc;
const el = () => document.getElementById('v-markets');
if(!M){ return; }
const SEGS = Object.keys(M.segments), TIERS = M.tiers;
const SEG_SHORT = {chips:'Chips & semis', infra:'Infra, cloud & power', software:'Software & platforms', consumer:'Consumer & internet', robotics:'Robotics & autonomy', other:'Other'};
const q = new URLSearchParams(location.search);
const st = {
  seg: new Set(q.has('mseg') ? q.get('mseg').split(',').filter(s => SEGS.includes(s)) : SEGS),
  tier: new Set(q.has('mtier') ? q.get('mtier').split(',').map(t => TIERS[+t]).filter(Boolean) : TIERS),
  group: q.get('mgroup') === 'seg' ? 'seg' : 'tier',
  sort: ['cap','day','y1','name'].includes(q.get('msort')) ? q.get('msort') : 'cap',
  find: ''
};
const DASH = '<span class="mut">—</span>';
const num = (v, d = 2) => v == null ? DASH : v.toLocaleString('en-US', {minimumFractionDigits: d, maximumFractionDigits: d});
const pct = v => v == null ? DASH : `<span class="dl ${v > 0 ? 'up' : v < 0 ? 'down' : ''}">${v > 0 ? '+' : ''}${v.toFixed(Math.abs(v) >= 100 ? 0 : 1)}%</span>`;
const cap = v => v == null ? DASH : v >= 1e12 ? `$${(v/1e12).toFixed(2)}T` : v >= 1e9 ? `$${(v/1e9).toFixed(v >= 1e11 ? 0 : 1)}B` : `$${(v/1e6).toFixed(0)}M`;
const capTitle = r => r.cap == null ? 'Market cap not available from the source' :
  `Reported market cap ${r.capCcy && r.capCcy !== 'USD' ? `${(r.capLocal/1e9).toLocaleString('en-US',{maximumFractionDigits:0})}B ${r.capCcy} → USD at the fetched FX rate` : ''} · as of ${r.capDate || 'unknown date'}`;
const price = r => r.price == null ? DASH : `${num(r.price, r.price < 1 ? 3 : (r.ccy && r.ccy !== 'USD' && r.price >= 1000) ? 0 : 2)}${r.ccy && r.ccy !== 'USD' ? ` <span class="d">${esc(r.ccy)}</span>` : ''}`;
const sorters = {cap: (a,b) => (b.cap ?? -1) - (a.cap ?? -1), day: (a,b) => (b.day ?? -1e9) - (a.day ?? -1e9), y1: (a,b) => (b.y1 ?? -1e9) - (a.y1 ?? -1e9), name: (a,b) => (a.name || a.t).localeCompare(b.name || b.t)};
const TIP = 'Click to toggle · Alt/Option-click or double-click to show only this one';
const chipRow = (kind, keys, label) => `<div class="tgroup"><span class="tl" id="mk-${kind}-l">${label}</span>
  <span class="qsel" role="group" aria-label="Quick select ${label.toLowerCase()}"><button type="button" class="qbtn" data-mqall="${kind}" title="Select all">All</button><button type="button" class="qbtn" data-mqnone="${kind}" title="Clear all">None</button></span>
  <div class="chips" role="group" aria-labelledby="mk-${kind}-l">${keys.map(k => `<button type="button" class="chip" data-m${kind}="${esc(k)}" title="${TIP}">${esc(kind === 'seg' ? SEG_SHORT[k] : k)} <span class="cnt">${M.rows.filter(r => kind === 'seg' ? r.seg === k : r.tier === k).length}</span></button>`).join('')}</div></div>`;

function rowsHtml(list){
  return list.map(r => `<tr${r.note ? ` title="${esc(r.note)}"` : ''}>
    <td data-l="Ticker"><a class="tk" href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.t)}</a></td>
    <td data-l="Company" class="nm"${r.name ? ` title="${esc(r.name + (r.note ? " - " + r.note : ""))}"` : ""}>${r.name ? esc(r.name) : DASH}${r.note ? ' <span class="d" aria-hidden="true">ⓘ</span>' : ''}</td>
    <td data-l="Segment"><span class="mseg s-${r.seg}">${esc(SEG_SHORT[r.seg])}</span></td>
    <td class="r" data-l="Price">${price(r)}</td>
    <td class="r" data-l="Day">${pct(r.day)}</td>
    <td class="r" data-l="Market cap" title="${esc(capTitle(r))}">${cap(r.cap)}</td>
    <td class="r" data-l="1Y">${pct(r.y1)}</td>
    <td data-l="Quote"><a href="${esc(r.url)}" target="_blank" rel="noopener" aria-label="${esc(r.t)} quote on Yahoo Finance">Quote ↗</a></td></tr>`).join('');
}
function table(){
  const f = st.find.trim().toLowerCase();
  const list = M.rows.filter(r => st.seg.has(r.seg) && (r.tier ? st.tier.has(r.tier) : st.tier.size === TIERS.length) && (!f || r.t.toLowerCase().includes(f) || (r.name || '').toLowerCase().includes(f))).sort(sorters[st.sort]);
  const groups = st.group === 'tier' ? [...TIERS, null].map(t => [t ? `Market cap ${t}` : 'Market cap unknown', list.filter(r => r.tier === t)])
                                     : SEGS.map(s => [M.segments[s], list.filter(r => r.seg === s)]);
  const body = groups.filter(([, l]) => l.length).map(([h, l]) => `<tbody><tr class="grp"><th colspan="8">${esc(h)} <span class="d">· ${l.length}</span></th></tr>${rowsHtml(l)}</tbody>`).join('');
  return {n: list.length, html: list.length ? `<table class="mkt"><thead><tr><th>Ticker</th><th>Company</th><th>Segment</th><th class="r">Price</th><th class="r">Day</th><th class="r">Market cap</th><th class="r">1Y</th><th>Link</th></tr></thead>${body}</table>`
    : `<div class="note" style="padding:10px">No companies match these filters. <button type="button" class="qbtn" data-mreset>Show all</button></div>`};
}
const unicorns = () => `<table class="mkt uni"><thead><tr><th>Company</th><th>What</th><th class="r">Latest reported valuation</th><th>Date</th><th>Status</th><th>Source</th></tr></thead><tbody>
  ${[...M.unicorns].sort((a,b) => (b.valuation_usd ?? 0) - (a.valuation_usd ?? 0)).map(u => `<tr>
    <td data-l="Company"><b>${esc(u.name)}</b></td><td data-l="What">${esc(u.what)}</td>
    <td class="r" data-l="Valuation"><b>${cap(u.valuation_usd)}</b><div class="d">${esc(u.valuation_text)}</div></td>
    <td data-l="Date">${esc(u.date.length === 7 ? new Date(u.date + '-01T12:00').toLocaleDateString('en-US',{month:'short',year:'numeric'}) : U.fmtD(u.date))}</td>
    <td data-l="Status"><span class="priv">PRIVATE · NOT TRADABLE</span><div class="d">${esc(u.status)}</div></td>
    <td data-l="Source"><a href="${esc(u.url)}" target="_blank" rel="noopener">${esc(u.source)} ↗</a></td></tr>`).join('')}</tbody></table>`;

function summary(){
  const cell = (lbl, n) => `<div class="mstat"><b>${n}</b><span>${esc(lbl)}</span></div>`;
  return `<div class="mstats">${TIERS.map(t => cell(t, M.rows.filter(r => r.tier === t).length)).join('')}</div>`;
}
function syncChips(root){
  ['seg','tier'].forEach(k => {
    root.querySelectorAll(`[data-m${k}]`).forEach(b => { const on = st[k].has(b.dataset['m' + k]); b.classList.toggle('on', on); b.setAttribute('aria-pressed', on); });
    const total = k === 'seg' ? SEGS.length : TIERS.length;
    root.querySelectorAll(`[data-mqall="${k}"]`).forEach(b => b.setAttribute('aria-disabled', st[k].size === total));
    root.querySelectorAll(`[data-mqnone="${k}"]`).forEach(b => b.setAttribute('aria-disabled', st[k].size === 0));
  });
}
function renderTable(){
  const root = el(), t = table();
  root.querySelector('#mk-table').innerHTML = t.html;
  root.querySelector('#mk-count').textContent = `${t.n} of ${M.rows.length} companies`;
  syncChips(root);
}
function render(){
  const root = el(); if(!root) return;
  const asOf = M.pricesAsOfLabel || M.asOfLabel;
  root.innerHTML = `<h2>Markets · AI stocks</h2>
   <div class="sub">${M.rows.length} publicly traded AI-related companies (US and major foreign listings), grouped by market-cap tier, plus private AI unicorns. Each company sits in one primary segment.</div>
   <div class="caveat" role="note"><b>Not investment advice. Data delayed, as of ${esc(asOf)}.</b> Source: ${esc(M.source)}; fetched ${esc(M.asOfLabel)}. Market caps are the source's latest reported values, converted to USD for non-US listings; 1Y = change in the last year's daily closes. A dash means the value could not be fetched.</div>
   ${summary()}
   <div class="toolbar">${chipRow('seg', SEGS, 'Segment')}</div>
   <div class="toolbar">${chipRow('tier', TIERS, 'Market cap')}</div>
   <div class="toolbar">
     <div class="tgroup"><span class="tl">Group</span><div class="seg2" id="mk-group"><button type="button" data-g="tier" class="${st.group==='tier'?'on':''}">By tier</button><button type="button" data-g="seg" class="${st.group==='seg'?'on':''}">By segment</button></div></div>
     <div class="tgroup"><label class="tl" for="mk-sort">Sort</label><select id="mk-sort"><option value="cap">Market cap</option><option value="day">Day change</option><option value="y1">1-year change</option><option value="name">Name A–Z</option></select></div>
     <div class="tgroup"><label class="tl" for="mk-find">Find</label><input id="mk-find" type="search" placeholder="Ticker or name" autocomplete="off"></div>
     <span class="d" id="mk-count" aria-live="polite"></span>
   </div>
   <div class="tblwrap mk-wrap" id="mk-table"></div>
   <!-- SPONSOR SLOT: reserved for a possible future sponsor/affiliate block. Intentionally empty and hidden; no affiliate links. -->
   <div id="mk-sponsor" class="sponsor-slot" data-slot="sponsor" hidden aria-hidden="true"></div>
   <h3 class="h3" style="margin-top:14px">AI unicorns · private, valued above $1B</h3>
   <div class="gapnote"><b>Private companies, not tradable on public exchanges.</b> Valuations are the latest reported funding-round or transaction figures with their date and source; they are not live prices. ${M.unicornNotes.map(esc).join(' ')}</div>
   <div class="tblwrap mk-wrap">${unicorns()}</div>
   <div class="d" style="margin-top:6px">Refresh: <code>python3 tools/refresh-markets.py</code> rebuilds data/markets.js; unicorn rows are curated by hand in tools/markets-universe.json.</div>`;
  root.querySelector('#mk-sort').value = st.sort;
  root.querySelector('#mk-sort').onchange = e => { st.sort = e.target.value; renderTable(); };
  root.querySelector('#mk-find').oninput = e => { st.find = e.target.value; renderTable(); };
  root.querySelectorAll('#mk-group button').forEach(b => b.onclick = () => { st.group = b.dataset.g; root.querySelectorAll('#mk-group button').forEach(x => x.classList.toggle('on', x === b)); renderTable(); });
  ['seg','tier'].forEach(k => {
    const all = k === 'seg' ? SEGS : TIERS;
    root.querySelectorAll(`[data-m${k}]`).forEach(b => { const v = b.dataset['m' + k];
      const solo = () => { st[k] = new Set([v]); renderTable(); };
      b.onclick = e => { if(e.altKey){ e.preventDefault(); return solo(); } st[k].has(v) ? st[k].delete(v) : st[k].add(v); renderTable(); };
      b.ondblclick = e => { e.preventDefault(); solo(); };
      b.onkeydown = e => { if(e.altKey && (e.key === 'Enter' || e.key === ' ')){ e.preventDefault(); solo(); } };
    });
    root.querySelectorAll(`[data-mqall="${k}"]`).forEach(b => b.onclick = () => { st[k] = new Set(all); renderTable(); });
    root.querySelectorAll(`[data-mqnone="${k}"]`).forEach(b => b.onclick = () => { st[k] = new Set(); renderTable(); });
  });
  root.querySelector('#mk-table').addEventListener('click', e => { if(e.target.closest('[data-mreset]')){ st.seg = new Set(SEGS); st.tier = new Set(TIERS); st.find = ''; root.querySelector('#mk-find').value = ''; renderTable(); } });
  renderTable();
}
window.MK = {render, state: st};
render();
})();
